import React, { createContext, useContext, useEffect, useState, useCallback } from "react";
import axios from "axios";

//const API = `${process.env.REACT_APP_API_URL || "http://localhost:8000"}/api`;
const API = "https://biblioteca-backend-3l9s.onrender.com/api";
const LibraryContext = createContext(null);

export function LibraryProvider({ children }) {
  // Authentication state
  const [currentUser, setCurrentUser] = useState(() => {
    const stored = localStorage.getItem('currentUser');
    return stored ? JSON.parse(stored) : null;
  });
  const [token, setToken] = useState(() => localStorage.getItem('token') || null);
  const [error, setError] = useState(null);
  const [isLoading, setIsLoading] = useState(false);

  // Navigation state for the modal
  const [modalOpen, setModalOpen] = useState(false);
  const [level, setLevel] = useState(0); // 0: Niveles, 1: Grados, 2: Materias
  const [nivelId, setNivelId] = useState(null);
  const [gradoId, setGradoId] = useState(null);

  // Links: { [gradoId]: { [materiaId]: url } }
  const [links, setLinks] = useState({});
  const [loading, setLoading] = useState(false);

  // Axios interceptor para agregar token
  useEffect(() => {
    if (token) {
      axios.defaults.headers.common['Authorization'] = `Bearer ${token}`;
    } else {
      delete axios.defaults.headers.common['Authorization'];
    }
  }, [token]);

  const refreshLinks = useCallback(async () => {
    try {
      setLoading(true);
      const res = await axios.get(`${API}/links`);
      setLinks(res.data || {});
    } catch (e) {
      console.error("Error loading links", e);
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    refreshLinks();
  }, [refreshLinks]);

  // ---- Authentication Functions ----
  const login = async (username, password) => {
    setError(null);
    setIsLoading(true);
    try {
      const res = await axios.post(`${API}/auth/login`, {
        username,
        password,
      });

      const { access_token, user } = res.data;
      setToken(access_token);
      setCurrentUser(user);
      localStorage.setItem('token', access_token);
      localStorage.setItem('currentUser', JSON.stringify(user));
      axios.defaults.headers.common['Authorization'] = `Bearer ${access_token}`;
      return true;
    } catch (err) {
      const errorMsg = err.response?.data?.detail || "Error al iniciar sesión";
      setError(errorMsg);
      return false;
    } finally {
      setIsLoading(false);
    }
  };

  const logout = () => {
    setToken(null);
    setCurrentUser(null);
    setError(null);
    localStorage.removeItem('token');
    localStorage.removeItem('currentUser');
    delete axios.defaults.headers.common['Authorization'];
  };

  // ---- User Management (Admin only) ----
  const createUser = async (username, password, role = "profesor") => {
    setError(null);
    setIsLoading(true);
    try {
      const res = await axios.post(`${API}/admin/users`, {
        username,
        password,
        role,
      });
      return res.data;
    } catch (err) {
      const errorMsg = err.response?.data?.detail || "Error al crear usuario";
      setError(errorMsg);
      return null;
    } finally {
      setIsLoading(false);
    }
  };

  const listUsers = async () => {
    setError(null);
    setIsLoading(true);
    try {
      const res = await axios.get(`${API}/admin/users`);
      return res.data;
    } catch (err) {
      const errorMsg = err.response?.data?.detail || "Error al cargar usuarios";
      setError(errorMsg);
      return null;
    } finally {
      setIsLoading(false);
    }
  };

  const updateUser = async (userId, role, isActive) => {
    setError(null);
    setIsLoading(true);
    try {
      const res = await axios.patch(`${API}/admin/users/${userId}`, {
        role,
        is_active: isActive,
      });
      return res.data;
    } catch (err) {
      const errorMsg = err.response?.data?.detail || "Error al actualizar usuario";
      setError(errorMsg);
      return null;
    } finally {
      setIsLoading(false);
    }
  };

  // ---- Audit Logs (Admin only) ----
  const getAuditLogs = async (limit = 100) => {
    setError(null);
    setIsLoading(true);
    try {
      const res = await axios.get(`${API}/admin/audit-logs?limit=${limit}`);
      return res.data;
    } catch (err) {
      const errorMsg = err.response?.data?.detail || "Error al cargar auditoría";
      setError(errorMsg);
      return null;
    } finally {
      setIsLoading(false);
    }
  };

  const getUserAuditLogs = async (userId, limit = 50) => {
    setError(null);
    try {
      const res = await axios.get(`${API}/admin/audit-logs/user/${userId}?limit=${limit}`);
      return res.data;
    } catch (err) {
      console.error("Error loading user audit logs:", err);
      return null;
    }
  };

  const getResourceAuditLogs = async (resourceId) => {
    setError(null);
    try {
      const res = await axios.get(`${API}/admin/audit-logs/resource/${resourceId}`);
      return res.data;
    } catch (err) {
      console.error("Error loading resource audit logs:", err);
      return null;
    }
  };

  const openModal = () => {
    setLevel(0);
    setNivelId(null);
    setGradoId(null);
    setModalOpen(true);
  };
  const closeModal = () => setModalOpen(false);

  const goToNivel = (id) => { setNivelId(id); setLevel(1); };
  const goToGrado = (id) => { setGradoId(id); setLevel(2); };
  const goBack = () => {
    if (level === 2) { setLevel(1); setGradoId(null); }
    else if (level === 1) { setLevel(0); setNivelId(null); }
  };

  const saveLink = async (gradoIdArg, materiaId, url) => {
    if (!currentUser) {
      setError("Debes iniciar sesión para guardar enlaces");
      return null;
    }
    try {
      const res = await axios.post(`${API}/links`, {
        grado_id: gradoIdArg,
        materia_id: materiaId,
        url,
      });
      setLinks((prev) => ({
        ...prev,
        [gradoIdArg]: { ...(prev[gradoIdArg] || {}), [materiaId]: res.data.url },
      }));
      setError(null);
      return res.data;
    } catch (err) {
      const errorMsg = err.response?.data?.detail || "Error al guardar enlace";
      setError(errorMsg);
      return null;
    }
  };

  const removeLink = async (gradoIdArg, materiaId) => {
    if (!currentUser) {
      setError("Debes iniciar sesión para eliminar enlaces");
      return;
    }
    try {
      await axios.delete(`${API}/links/${gradoIdArg}/${materiaId}`);
      setLinks((prev) => {
        const next = { ...prev };
        if (next[gradoIdArg]) {
          const copy = { ...next[gradoIdArg] };
          delete copy[materiaId];
          next[gradoIdArg] = copy;
        }
        return next;
      });
      setError(null);
    } catch (err) {
      const errorMsg = err.response?.data?.detail || "Error al eliminar enlace";
      setError(errorMsg);
    }
  };

  const value = {
    // Auth
    currentUser,
    token,
    error,
    isLoading,
    login,
    logout,

    // User Management
    createUser,
    listUsers,
    updateUser,

    // Audit Logs
    getAuditLogs,
    getUserAuditLogs,
    getResourceAuditLogs,

    // Modal navigation
    modalOpen,
    level,
    nivelId,
    gradoId,
    links,
    loading,

    openModal,
    closeModal,
    goToNivel,
    goToGrado,
    goBack,

    saveLink,
    removeLink,
    refreshLinks,
  };

  return <LibraryContext.Provider value={value}>{children}</LibraryContext.Provider>;
}

export const useLibrary = () => {
  const ctx = useContext(LibraryContext);
  if (!ctx) throw new Error("useLibrary must be used within LibraryProvider");
  return ctx;
};
