import React, { useState } from "react";
import { Library, Menu, X, LogOut, Settings } from "lucide-react";
import { useLibrary } from "../context/LibraryContext";
import { useNavigate } from "react-router-dom";

const NAV_LINKS = [
  { id: "inicio", label: "Inicio", href: "#inicio" },
  { id: "salones", label: "Salones", href: "#salones" },
  { id: "destacados", label: "Destacados", href: "#destacados" },
  { id: "buscar", label: "Buscar", href: "#buscar" },
];

export const Header = ({ onOpenLibrary }) => {
  const [open, setOpen] = useState(false);
  const [userMenuOpen, setUserMenuOpen] = useState(false);
  const { currentUser, logout } = useLibrary();
  const navigate = useNavigate();

  const handleLogout = () => {
    logout();
    setUserMenuOpen(false);
    navigate("/login");
  };

  const handleAdminPanel = () => {
    setUserMenuOpen(false);
    navigate("/admin");
  };

  return (
    <header
      data-testid="app-header"
      className="fixed top-0 w-full z-40 backdrop-blur-2xl bg-[#020b04]/80 border-b border-[#c9a227]/20"
    >
      <div className="max-w-7xl mx-auto px-6 sm:px-8 lg:px-12 flex items-center justify-between h-20">
        {/* Logo */}
        <a href="#inicio" className="flex items-center gap-3 group" data-testid="header-logo">
          <div className="w-11 h-11 rounded-full border border-[#c9a227]/50 bg-[#051a09] flex items-center justify-center shadow-[0_0_20px_rgba(201,162,39,0.2)] group-hover:shadow-[0_0_28px_rgba(201,162,39,0.45)] transition-shadow">
            <Library className="w-5 h-5 text-[#c9a227]" />
          </div>
          <div className="leading-tight">
            <div className="font-cinzel text-[#c9a227] text-lg tracking-wider">RGB</div>
            <div className="font-dm-sans text-[10px] uppercase tracking-[0.2em] text-[#a3b3a6]">
              Biblioteca Escolar
            </div>
          </div>
        </a>

        {/* Desktop nav */}
        <nav className="hidden md:flex items-center gap-10">
          {NAV_LINKS.map((l) => (
            <a
              key={l.id}
              href={l.href}
              data-testid={`nav-link-${l.id}`}
              className="font-dm-sans text-sm tracking-wide text-[#f4f1e1] hover:text-[#c9a227] transition-colors"
            >
              {l.label}
            </a>
          ))}
          {!currentUser ? (
            <>
              <button
                onClick={() => navigate("/login")}
                data-testid="header-login-btn"
                className="font-dm-sans text-sm tracking-wide text-[#f4f1e1] hover:text-[#c9a227] transition-colors"
              >
                Iniciar sesión
              </button>
              <button
                onClick={onOpenLibrary}
                data-testid="header-open-library-btn"
                className="btn-gold px-5 py-2 rounded-sm text-sm font-dm-sans font-semibold tracking-wide"
              >
                Abrir Biblioteca
              </button>
            </>
          ) : (
            <>
              <button
                onClick={onOpenLibrary}
                data-testid="header-open-library-btn"
                className="btn-gold px-5 py-2 rounded-sm text-sm font-dm-sans font-semibold tracking-wide"
              >
                Abrir Biblioteca
              </button>
              <div className="relative">
                <button
                  onClick={() => setUserMenuOpen(!userMenuOpen)}
                  data-testid="header-user-menu"
                  className="flex items-center gap-2 px-3 py-2 rounded text-sm text-[#c9a227] hover:bg-[#c9a227]/10 transition-colors"
                >
                  {currentUser.username}
                  {currentUser.role === "admin" && (
                    <span className="text-xs bg-red-500/30 text-red-400 px-2 py-1 rounded">
                      Admin
                    </span>
                  )}
                </button>
                {userMenuOpen && (
                  <div className="absolute top-full right-0 mt-2 w-48 bg-[#051a09] border border-[#c9a227]/20 rounded shadow-lg z-50">
                    {currentUser.role === "admin" && (
                      <>
                        <button
                          onClick={handleAdminPanel}
                          className="w-full text-left px-4 py-2 hover:bg-[#c9a227]/10 text-[#f4f1e1] flex items-center gap-2 border-b border-[#c9a227]/10"
                          data-testid="header-admin-panel"
                        >
                          <Settings size={16} />
                          Panel de Admin
                        </button>
                      </>
                    )}
                    <button
                      onClick={handleLogout}
                      className="w-full text-left px-4 py-2 hover:bg-red-500/10 text-red-400 flex items-center gap-2"
                      data-testid="header-logout"
                    >
                      <LogOut size={16} />
                      Cerrar sesión
                    </button>
                  </div>
                )}
              </div>
            </>
          )}
        </nav>

        {/* Mobile */}
        <button
          className="md:hidden text-[#c9a227] p-2"
          onClick={() => setOpen((v) => !v)}
          data-testid="mobile-menu-toggle"
          aria-label="Menú"
        >
          {open ? <X className="w-6 h-6" /> : <Menu className="w-6 h-6" />}
        </button>
      </div>

      {open && (
        <div className="md:hidden border-t border-[#c9a227]/15 bg-[#020b04]/95 px-6 py-4 flex flex-col gap-4 animate-fade-in">
          {NAV_LINKS.map((l) => (
            <a
              key={l.id}
              href={l.href}
              onClick={() => setOpen(false)}
              data-testid={`mobile-nav-link-${l.id}`}
              className="font-dm-sans text-sm text-[#f4f1e1]"
            >
              {l.label}
            </a>
          ))}
          {!currentUser ? (
            <>
              <button
                onClick={() => {
                  setOpen(false);
                  navigate("/login");
                }}
                data-testid="mobile-login-btn"
                className="font-dm-sans text-sm text-[#c9a227] px-4 py-2"
              >
                Iniciar sesión
              </button>
              <button
                onClick={() => { setOpen(false); onOpenLibrary(); }}
                data-testid="mobile-open-library-btn"
                className="btn-gold px-4 py-2 rounded-sm text-sm font-dm-sans font-semibold"
              >
                Abrir Biblioteca
              </button>
            </>
          ) : (
            <>
              <button
                onClick={() => { setOpen(false); onOpenLibrary(); }}
                data-testid="mobile-open-library-btn"
                className="btn-gold px-4 py-2 rounded-sm text-sm font-dm-sans font-semibold"
              >
                Abrir Biblioteca
              </button>
              <div className="border-t border-[#c9a227]/15 pt-4 mt-4">
                <p className="text-sm text-[#c9a227] mb-2">
                  {currentUser.username} {currentUser.role === "admin" && "(Admin)"}
                </p>
                {currentUser.role === "admin" && (
                  <button
                    onClick={() => {
                      setOpen(false);
                      navigate("/admin");
                    }}
                    className="w-full text-left px-4 py-2 mb-2 hover:bg-[#c9a227]/10 text-[#f4f1e1] flex items-center gap-2"
                  >
                    <Settings size={16} />
                    Panel de Admin
                  </button>
                )}
                <button
                  onClick={handleLogout}
                  className="w-full text-left px-4 py-2 hover:bg-red-500/10 text-red-400 flex items-center gap-2"
                >
                  <LogOut size={16} />
                  Cerrar sesión
                </button>
              </div>
            </>
          )}
        </div>
      )}
    </header>
  );
};
