import { useState, useEffect } from "react";
import { useLibrary } from "../context/LibraryContext";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "./ui/card";
import { Button } from "./ui/button";
import { Input } from "./ui/input";
import { Alert, AlertDescription } from "./ui/alert";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "./ui/table";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
} from "./ui/dialog";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "./ui/select";
import { Users, LogOut, Activity, Plus, Trash2, CheckCircle, XCircle } from "lucide-react";

export default function AdminPanel() {
  const {
    currentUser,
    logout,
    createUser,
    listUsers,
    getAuditLogs,
    error,
    isLoading,
  } = useLibrary();

  const [users, setUsers] = useState([]);
  const [auditLogs, setAuditLogs] = useState([]);
  const [newUser, setNewUser] = useState({ username: "", password: "", role: "profesor" });
  const [showCreateUser, setShowCreateUser] = useState(false);
  const [showAuditLogs, setShowAuditLogs] = useState(false);
  const [activeTab, setActiveTab] = useState("usuarios");

  // Cargar usuarios
  const handleLoadUsers = async () => {
    const data = await listUsers();
    if (data) setUsers(data);
  };

  // Cargar logs de auditoría
  const handleLoadAuditLogs = async () => {
    const data = await getAuditLogs();
    if (data) setAuditLogs(data);
  };

  // Crear usuario
  const handleCreateUser = async (e) => {
    e.preventDefault();
    if (!newUser.username || !newUser.password) {
      alert("Por favor completa todos los campos");
      return;
    }

    const success = await createUser(newUser.username, newUser.password, newUser.role);
    if (success) {
      setNewUser({ username: "", password: "", role: "profesor" });
      setShowCreateUser(false);
      handleLoadUsers();
    }
  };

  useEffect(() => {
    if (activeTab === "usuarios") {
      handleLoadUsers();
    } else if (activeTab === "auditoria") {
      handleLoadAuditLogs();
    }
  }, [activeTab]);

  if (!currentUser) {
    return null;
  }

  if (currentUser.role !== "admin") {
    return (
      <Alert className="m-4 border-red-500/50 bg-red-500/10">
        <AlertDescription className="text-red-400">
          No tienes acceso al panel de administración
        </AlertDescription>
      </Alert>
    );
  }

  return (
    <div className="p-6 space-y-6 max-w-7xl mx-auto">
      {/* Header */}
      <div className="flex justify-between items-center">
        <div>
          <h1 className="text-3xl font-cinzel text-[#c9a227] mb-2">Panel de Administración</h1>
          <p className="text-gray-400">Bienvenido, {currentUser.username}</p>
        </div>
        <Button
          onClick={logout}
          variant="destructive"
          className="gap-2"
          data-testid="admin-logout"
        >
          <LogOut size={18} />
          Cerrar sesión
        </Button>
      </div>

      {error && (
        <Alert className="border-red-500/50 bg-red-500/10">
          <AlertDescription className="text-red-400">{error}</AlertDescription>
        </Alert>
      )}

      {/* Tabs */}
      <div className="flex gap-4 border-b border-[#c9a227]/20">
        <button
          onClick={() => setActiveTab("usuarios")}
          className={`pb-3 px-4 font-medium transition-colors ${
            activeTab === "usuarios"
              ? "border-b-2 border-[#c9a227] text-[#c9a227]"
              : "text-gray-400 hover:text-gray-300"
          }`}
          data-testid="tab-usuarios"
        >
          <Users className="inline mr-2" size={18} />
          Usuarios
        </button>
        <button
          onClick={() => setActiveTab("auditoria")}
          className={`pb-3 px-4 font-medium transition-colors ${
            activeTab === "auditoria"
              ? "border-b-2 border-[#c9a227] text-[#c9a227]"
              : "text-gray-400 hover:text-gray-300"
          }`}
          data-testid="tab-auditoria"
        >
          <Activity className="inline mr-2" size={18} />
          Auditoría
        </button>
      </div>

      {/* Usuarios Tab */}
      {activeTab === "usuarios" && (
        <div className="space-y-4">
          <div className="flex justify-between items-center">
            <h2 className="text-xl font-semibold text-gray-200">Gestión de Usuarios</h2>
            <Dialog open={showCreateUser} onOpenChange={setShowCreateUser}>
              <DialogTrigger asChild>
                <Button className="gap-2 bg-[#c9a227] hover:bg-[#d4b140] text-[#020b04]">
                  <Plus size={18} />
                  Crear Usuario
                </Button>
              </DialogTrigger>
              <DialogContent className="bg-[#051a09] border-[#c9a227]/20">
                <DialogHeader>
                  <DialogTitle className="text-[#c9a227]">Crear Nuevo Usuario</DialogTitle>
                  <DialogDescription className="text-gray-400">
                    Completa los datos para crear un nuevo usuario
                  </DialogDescription>
                </DialogHeader>

                <form onSubmit={handleCreateUser} className="space-y-4">
                  <div>
                    <label className="text-sm font-medium text-gray-300">Usuario</label>
                    <Input
                      type="text"
                      placeholder="nombre de usuario"
                      value={newUser.username}
                      onChange={(e) =>
                        setNewUser({ ...newUser, username: e.target.value })
                      }
                      className="mt-1 bg-[#020b04]/50 border-[#c9a227]/30"
                      data-testid="create-user-username"
                    />
                  </div>

                  <div>
                    <label className="text-sm font-medium text-gray-300">Contraseña</label>
                    <Input
                      type="password"
                      placeholder="contraseña segura"
                      value={newUser.password}
                      onChange={(e) =>
                        setNewUser({ ...newUser, password: e.target.value })
                      }
                      className="mt-1 bg-[#020b04]/50 border-[#c9a227]/30"
                      data-testid="create-user-password"
                    />
                  </div>

                  <div>
                    <label className="text-sm font-medium text-gray-300">Rol</label>
                    <Select value={newUser.role} onValueChange={(value) =>
                      setNewUser({ ...newUser, role: value })
                    }>
                      <SelectTrigger className="mt-1 bg-[#020b04]/50 border-[#c9a227]/30">
                        <SelectValue />
                      </SelectTrigger>
                      <SelectContent className="bg-[#051a09] border-[#c9a227]/20">
                        <SelectItem value="profesor">Profesor</SelectItem>
                        <SelectItem value="admin">Administrador</SelectItem>
                      </SelectContent>
                    </Select>
                  </div>

                  <div className="flex gap-3 pt-4">
                    <Button
                      type="submit"
                      disabled={isLoading}
                      className="flex-1 bg-[#c9a227] hover:bg-[#d4b140] text-[#020b04]"
                      data-testid="create-user-submit"
                    >
                      {isLoading ? "Creando..." : "Crear Usuario"}
                    </Button>
                    <Button
                      type="button"
                      variant="outline"
                      onClick={() => setShowCreateUser(false)}
                      className="flex-1"
                    >
                      Cancelar
                    </Button>
                  </div>
                </form>
              </DialogContent>
            </Dialog>
          </div>

          {/* Users Table */}
          <Card className="border-[#c9a227]/20 bg-[#020b04]/50 backdrop-blur">
            <CardContent className="p-0">
              <Table>
                <TableHeader>
                  <TableRow className="border-[#c9a227]/20 hover:bg-transparent">
                    <TableHead className="text-[#c9a227]">Usuario</TableHead>
                    <TableHead className="text-[#c9a227]">Rol</TableHead>
                    <TableHead className="text-[#c9a227]">Estado</TableHead>
                    <TableHead className="text-[#c9a227]">Creado</TableHead>
                  </TableRow>
                </TableHeader>
                <TableBody>
                  {users.length === 0 ? (
                    <TableRow>
                      <TableCell colSpan="4" className="text-center py-8 text-gray-500">
                        No hay usuarios registrados
                      </TableCell>
                    </TableRow>
                  ) : (
                    users.map((user) => (
                      <TableRow key={user.id} className="border-[#c9a227]/10 hover:bg-[#c9a227]/5">
                        <TableCell className="font-medium text-gray-200">{user.username}</TableCell>
                        <TableCell>
                          <span className={`px-2 py-1 rounded text-sm font-medium ${
                            user.role === "admin"
                              ? "bg-red-500/20 text-red-400"
                              : "bg-blue-500/20 text-blue-400"
                          }`}>
                            {user.role === "admin" ? "Administrador" : "Profesor"}
                          </span>
                        </TableCell>
                        <TableCell>
                          {user.is_active ? (
                            <CheckCircle size={18} className="text-green-400" />
                          ) : (
                            <XCircle size={18} className="text-red-400" />
                          )}
                        </TableCell>
                        <TableCell className="text-gray-400 text-sm">
                          {new Date(user.created_at).toLocaleDateString("es-ES")}
                        </TableCell>
                      </TableRow>
                    ))
                  )}
                </TableBody>
              </Table>
            </CardContent>
          </Card>
        </div>
      )}

      {/* Auditoría Tab */}
      {activeTab === "auditoria" && (
        <div className="space-y-4">
          <h2 className="text-xl font-semibold text-gray-200">Registro de Auditoría</h2>

          <Card className="border-[#c9a227]/20 bg-[#020b04]/50 backdrop-blur">
            <CardContent className="p-0">
              <Table>
                <TableHeader>
                  <TableRow className="border-[#c9a227]/20 hover:bg-transparent">
                    <TableHead className="text-[#c9a227]">Usuario</TableHead>
                    <TableHead className="text-[#c9a227]">Acción</TableHead>
                    <TableHead className="text-[#c9a227]">Recurso</TableHead>
                    <TableHead className="text-[#c9a227]">Cambios</TableHead>
                    <TableHead className="text-[#c9a227]">Fecha</TableHead>
                  </TableRow>
                </TableHeader>
                <TableBody>
                  {auditLogs.length === 0 ? (
                    <TableRow>
                      <TableCell colSpan="5" className="text-center py-8 text-gray-500">
                        No hay registros de auditoría
                      </TableCell>
                    </TableRow>
                  ) : (
                    auditLogs.map((log) => (
                      <TableRow key={log.id} className="border-[#c9a227]/10 hover:bg-[#c9a227]/5">
                        <TableCell className="font-medium text-gray-200">{log.username}</TableCell>
                        <TableCell>
                          <span className={`px-2 py-1 rounded text-sm font-medium ${
                            log.action === "create"
                              ? "bg-green-500/20 text-green-400"
                              : log.action === "update"
                              ? "bg-blue-500/20 text-blue-400"
                              : "bg-red-500/20 text-red-400"
                          }`}>
                            {log.action === "create" && "Crear"}
                            {log.action === "update" && "Actualizar"}
                            {log.action === "delete" && "Eliminar"}
                          </span>
                        </TableCell>
                        <TableCell className="text-gray-300">{log.resource_type}</TableCell>
                        <TableCell className="text-gray-400 text-xs max-w-xs truncate">
                          {JSON.stringify(log.changes).substring(0, 50)}...
                        </TableCell>
                        <TableCell className="text-gray-400 text-sm">
                          {new Date(log.timestamp).toLocaleDateString("es-ES")} {new Date(log.timestamp).toLocaleTimeString("es-ES")}
                        </TableCell>
                      </TableRow>
                    ))
                  )}
                </TableBody>
              </Table>
            </CardContent>
          </Card>
        </div>
      )}
    </div>
  );
}
