import React, { useState } from "react";
import { NIVELES } from "../data/niveles";
import { Sprout, BookOpenText, GraduationCap, ArrowUpRight } from "lucide-react";
import { useLibrary } from "../context/LibraryContext";

const ICONS = { Sprout, BookOpenText, GraduationCap };

export const Categories = () => {
  const {openModal, goToNivel, setIsAdmin, isAdmin } = useLibrary();

  // ✅ estados arriba (correcto)
  const [showLogin, setShowLogin] = useState(false);
  const [password, setPassword] = useState("");

  const handleClick = (nivelId) => {
    openModal();
    setTimeout(() => goToNivel(nivelId), 10);
  };

  const handleLogin = () => {
    if (password === "1234") {
      setIsAdmin(true);
      setShowLogin(false);
      LocalStorage.setItem("isAdmin", "true");
      alert("Admin activado");
    } else {
      alert("Contraseña incorrecta");
    }
  };

  return (
    <section
      id="salones"
      data-testid="categories-section"
      className="py-24 relative"
    >
      <div className="max-w-7xl mx-auto px-6 sm:px-8 lg:px-12">

        {/* BOTÓN ADMIN */}
        {!isAdmin ? (
          <button
            onClick={() => setShowLogin(true)}
            className="mb-6 px-4 py-2 bg-[#c9a227] text-black rounded"
          >
            Activar Admin
          </button>
        ) : (
          <button
            onClick={() => {
              setIsAdmin(false);
              setPassword("");
              setShowLogin(false);
            }}
            className="mb-6 px-4 py-2 bg-red-600 text-white rounded"
          >
            Cerrar sesión
          </button>
        )}

        {showLogin && (
          <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/70 p-4">
            <div className="w-full max-w-sm rounded-2xl bg-white p-6 shadow-xl">
              <h3 className="mb-4 text-xl font-bold text-slate-900">
                Iniciar sesión Admin
              </h3>
              <p className="mb-4 text-sm text-slate-600">
                Ingresa la contraseña para activar el modo admin.
              </p>
              <input
                type="password"
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                className="w-full rounded-lg border border-slate-300 px-4 py-3 text-slate-900 outline-none focus:border-[#c9a227]"
                placeholder="Contraseña"
              />
              <div className="mt-5 flex flex-wrap gap-3">
                <button
                  type="button"
                  onClick={handleLogin}
                  className="flex-1 rounded-lg bg-[#c9a227] px-4 py-3 text-sm font-semibold text-black"
                >
                  Entrar
                </button>
                <button
                  type="button"
                  onClick={() => {
                    setShowLogin(false);
                    setPassword("");
                  }}
                  className="flex-1 rounded-lg border border-slate-300 bg-white px-4 py-3 text-sm font-semibold text-slate-700"
                >
                  Cancelar
                </button>
              </div>
            </div>
          </div>
        )}

        {/* HEADER */}
        <div className="mb-14 max-w-2xl">
          <div className="font-dm-sans text-xs tracking-[0.3em] uppercase text-[#c9a227]/80 mb-3">
            Salones de Clase
          </div>
          <h2 className="font-cinzel text-4xl sm:text-5xl text-[#f4f1e1] leading-tight">
            Selecciona un{" "}
            <span className="text-[#c9a227] italic font-cormorant">
              nivel académico
            </span>
          </h2>
          <div className="divider-gold mt-8" />
        </div>

        {/* CARDS */}
        <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
          {NIVELES.map((nivel, idx) => {
            const Icon = ICONS[nivel.icon] || BookOpenText;

            return (
              <button
                key={nivel.id}
                onClick={() => handleClick(nivel.id)}
                className="group text-left glass rounded-lg p-8 relative overflow-hidden hover:border-[#c9a227]/50 transition-all duration-300 hover:-translate-y-1 animate-fade-up"
                style={{ animationDelay: `${idx * 0.08}s` }}
              >
                <div className="absolute top-0 right-0 w-24 h-24 bg-[#c9a227]/10 rounded-bl-full" />

                <div className="absolute top-5 right-5 text-[#c9a227]/70">
                  <ArrowUpRight className="w-5 h-5" />
                </div>

                <div className="relative">
                  <div className="w-14 h-14 rounded-full bg-[#c9a227]/10 flex items-center justify-center border border-[#c9a227]/30 mb-6">
                    <Icon className="w-6 h-6 text-[#c9a227]" />
                  </div>

                  <h3 className="font-cinzel text-3xl text-[#f4f1e1] mb-2">
                    {nivel.name}
                  </h3>

                  <div className="font-dm-sans text-xs uppercase text-[#c9a227] mb-5">
                    {nivel.subtitle}
                  </div>

                  <p className="font-cormorant text-lg text-[#a3b3a6]">
                    {nivel.description}
                  </p>

                  <div className="mt-8 text-[#c9a227]/80 text-xs uppercase">
                    {nivel.grados.length} grados disponibles
                  </div>
                </div>
              </button>
            );
          })}
        </div>
      </div>
    </section>
  );
};