import { useState } from "react";
import { useLibrary } from "../context/LibraryContext";
import { Alert, AlertDescription } from "./ui/alert";
import { Button } from "./ui/button";
import { Input } from "./ui/input";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "./ui/card";
import { Lock, User } from "lucide-react";

export default function Login() {
  const { login, error, isLoading } = useLibrary();
  const [username, setUsername] = useState("");
  const [password, setPassword] = useState("");

  const handleSubmit = async (e) => {
    e.preventDefault();
    await login(username, password);
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-[#020b04] to-[#051a09] flex items-center justify-center p-4">
      <Card className="w-full max-w-md border-[#c9a227]/20 bg-[#051a09]/80 backdrop-blur">
        <CardHeader className="space-y-2">
          <CardTitle className="text-2xl font-cinzel text-center text-[#c9a227]">
            Biblioteca RGB
          </CardTitle>
          <CardDescription className="text-center text-gray-400">
            Ingresa tus credenciales
          </CardDescription>
        </CardHeader>

        <CardContent>
          {error && (
            <Alert className="mb-4 border-red-500/50 bg-red-500/10">
              <AlertDescription className="text-red-400">{error}</AlertDescription>
            </Alert>
          )}

          <form onSubmit={handleSubmit} className="space-y-4">
            <div className="space-y-2">
              <label className="text-sm font-medium text-gray-300 flex items-center gap-2">
                <User size={16} /> Usuario
              </label>
              <Input
                type="text"
                placeholder="Tu usuario"
                value={username}
                onChange={(e) => setUsername(e.target.value)}
                disabled={isLoading}
                className="bg-[#020b04]/50 border-[#c9a227]/30 text-white placeholder-gray-500"
                data-testid="login-username"
              />
            </div>

            <div className="space-y-2">
              <label className="text-sm font-medium text-gray-300 flex items-center gap-2">
                <Lock size={16} /> Contraseña
              </label>
              <Input
                type="password"
                placeholder="Tu contraseña"
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                disabled={isLoading}
                className="bg-[#020b04]/50 border-[#c9a227]/30 text-white placeholder-gray-500"
                data-testid="login-password"
              />
            </div>

            <Button
              type="submit"
              disabled={isLoading || !username || !password}
              className="w-full bg-[#c9a227] hover:bg-[#d4b140] text-[#020b04] font-semibold"
              data-testid="login-submit"
            >
              {isLoading ? "Ingresando..." : "Ingresar"}
            </Button>
          </form>
        </CardContent>
      </Card>
    </div>
  );
}
